    private static var made: [String: NSImage] = [:]

    /// An icon, or one of the bar's drawings, as a template image.
    static func art(_ name: String) -> NSImage? {
        if let hit = made[name] { return hit }
        guard let body = paths[name] else { return nil }
        let svg = ##"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke-linecap="round" stroke-linejoin="round">"## + body + "</svg>"
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        made[name] = image
        return image
    }

